import {projectNavigation} from './oncall-navigation.js';
import {escapeHtml as esc} from './message-format.js';
import {localAt,localInstant,addDays} from './oncall-planning.js';
export function calendarView({root,w,calendar,mode,getMe,api,token,run,show,status}) {
 const settings=calendar.settings,archived=settings.archivedAt>0n,zone=Intl.DateTimeFormat().resolvedOptions().timeZone||'UTC';
 const nav=`<a class="back-link" href="#/oncall/${w.project.id}">← ${esc(w.project.name)}</a><div class="page-heading"><div><span class="eyebrow">ON-CALL</span><h2>${mode==='availability'?'Time off':'Project settings'}</h2><p class="lead">${mode==='availability'?'Declare unavailable time. A teammate still needs to accept any cover.':'People and roles are managed in Hub. Published history stays traceable.'}</p></div></div>${projectNavigation(w,mode)}`;
 const dt=n=>new Date(Number(n/1000000n)).toLocaleString();
 if(mode==='availability'){
  const tomorrow=addDays(localAt(Date.now(),zone).slice(0,10),1)+'T09:00';
  root.innerHTML=nav+(archived?'<p class="oc-issues">This project is archived.</p>':`<form id="availabilityForm" class="card oc-form"><label for="absencePerson">Who is unavailable?</label><select id="absencePerson">${w.members.filter(p=>w.canManage||p.id===getMe().id).map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('')}</select><div class="row"><div><label for="absenceStart">From · ${esc(zone)}</label><input id="absenceStart" type="datetime-local" value="${tomorrow}" required></div><div><label for="absenceEnd">Until</label><input id="absenceEnd" type="datetime-local" value="${tomorrow.slice(0,11)}18:00" required></div></div><p class="kv">Visible to this project’s response team. No medical details or private reason are collected. Other projects have their own availability.</p><button class="primary">Mark unavailable</button></form>`)+status+`<section class="card"><h3>Upcoming & recent availability</h3>${calendar.absences.filter(a=>!a.cancelledAt).sort((a,b)=>a.startAt<b.startAt?-1:1).map(a=>`<div class="oc-availability-row"><div><strong>${esc(a.name)}</strong><p>${esc(dt(a.startAt))} – ${esc(dt(a.endAt))}</p></div>${a.startAt>BigInt(Date.now())*1000000n&&(w.canManage||a.personId===getMe().id)?`<button data-remove-absence="${a.id}">Cancel</button>`:''}</div>`).join('')||'<p class="kv">No unavailable time recorded.</p>'}</section><p class="oc-footnote">Coverage warnings appear in the plan. New alerts skip an unavailable responder and follow escalation; an existing incident owner is retained. Availability records are deleted 93 days after they end.</p>`;
  const form=root.querySelector('form');if(form)form.onsubmit=e=>{e.preventDefault();try{const value=id=>root.querySelector('#'+id).value;const start=localInstant(value('absenceStart'),zone),end=localInstant(value('absenceEnd'),zone);run(e.submitter,()=>api().setOncallAbsence(token(),w.project.id,value('absencePerson'),start,end),()=>show(String(w.project.id),mode));}catch(e){root.querySelector('[data-oc-status]').textContent=e.message;}};
  root.querySelectorAll('[data-remove-absence]').forEach(b=>b.onclick=()=>run(b,()=>api().cancelOncallAbsence(token(),BigInt(b.dataset.removeAbsence)),()=>show(String(w.project.id),mode)));return;
 }
 if(!w.canManage){root.innerHTML=nav+'<p>Only Hub-assigned Desk administrators can change project settings.</p>';return;}
 root.innerHTML=nav+`<form id="projectSettings" class="card oc-form"><label for="projectTitle">Project name</label><input id="projectTitle" value="${esc(w.project.name)}" required maxlength="80"><label for="projectDescription">Description</label><input id="projectDescription" value="${esc(w.project.description)}" maxlength="300"><label for="projectServices">Services · comma separated</label><input id="projectServices" value="${esc(w.project.services.join(', '))}" required><p class="kv">You can add services. Existing names are retained because incidents and reports reference them.</p><label for="historyDays">Planning history · days after a period ends</label><input id="historyDays" type="number" min="400" max="3650" value="${settings.retentionDays}" required><p class="kv">Shorter retention takes effect after seven days. Open reporting drafts protect the related plan. Payroll statements have a separate retention policy.</p><button class="primary">Save settings</button></form>${status}<section class="card oc-form"><h3>${archived?'Restore project':'Archive project'}</h3><p>Archive after ending coverage, resolving incidents, pausing alert sources and disabling its status page. Reports and history remain available until retention removes them.</p><button id="archiveProject">${archived?'Restore project':'Archive project'}</button></section>`;
 root.querySelector('#projectSettings').onsubmit=e=>{e.preventDefault();const val=id=>root.querySelector('#'+id).value;run(e.submitter,()=>api().updateOncallProject(token(),w.project.id,settings.revision,val('projectTitle').trim(),val('projectDescription').trim(),val('projectServices').split(',').map(s=>s.trim()).filter(Boolean),BigInt(val('historyDays'))),()=>show(String(w.project.id),mode));};
 root.querySelector('#archiveProject').onclick=e=>run(e.currentTarget,()=>api().archiveOncallProject(token(),w.project.id,settings.revision,!archived),()=>show(String(w.project.id),mode));
}
